<?php require __DIR__ . '/../partials/header.php'; ?>
<div class="card"><div class="card-header"><h1>Stock Levels</h1><p>Update your product stock levels.</p></div><?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?><?php if($successMsg):?><div class="alert alert-success"><?php echo e($successMsg);?></div><?php endif;?>
<?php if(!$products):?><p class="muted">No products yet.</p><?php else:?><table class="data-table"><tr><th>ID</th><th>Name</th><th>Selling</th><th>Cost</th><th>Margin %</th><th>Stock</th><th>Update</th></tr><?php foreach($products as $p):$low=(int)$p['stock_qty']<=5;?><tr style="<?php echo $low?'background:#fff3d0;':'';?>"><td>#<?php echo e($p['id']);?></td><td><?php echo e($p['name']);?> <?php if($low):?><span class="small" style="color:#b36b00;">LOW</span><?php endif;?></td><td>TK <?php echo e(number_format((float)$p['selling_price'],2));?></td><td>TK <?php echo e(number_format((float)$p['cost_price'],2));?></td><td><?php echo $p['profit_margin']!==null?e(number_format((float)$p['profit_margin'],2)).'%':'—';?></td><td><?php echo e($p['stock_qty']);?></td><td><form method="post" action="<?php echo e(url_for('seller','stock'));?>"><?php echo csrf_field();?><input type="hidden" name="product_id" value="<?php echo e($p['id']);?>"><input type="number" min="0" name="stock_qty" value="<?php echo e($p['stock_qty']);?>" style="width:80px;padding:6px;"><button class="btn btn-primary btn-small">Save</button></form></td></tr><?php endforeach;?></table><?php endif;?></div>
<div class="card"><div class="card-header"><h2>Pending Orders</h2></div><?php if(!$pending):?><p class="muted">No pending orders.</p><?php else:?><table class="data-table"><tr><th>Order #</th><th>Customer</th><th>Product</th><th>Qty × Price</th><th>Total</th><th>Status</th><th>Date</th></tr><?php foreach($pending as $o):?><tr><td>#<?php echo e($o['order_id']);?></td><td><?php echo e($o['customer_name']);?></td><td><?php echo e($o['product_name']);?></td><td><?php echo e($o['qty']);?> × TK <?php echo e(number_format((float)$o['price'],2));?></td><td>TK <?php echo e(number_format((float)$o['total_amount'],2));?></td><td><?php echo e($o['delivery_status']);?></td><td class="small"><?php echo e($o['created_at']);?></td></tr><?php endforeach;?></table><?php endif;?></div>
<?php require __DIR__ . '/../partials/footer.php'; ?>
